import Foundation
import CoreImage
import AppKit

// The bitmap is generated by ZXing on Android; macOS independently decodes the screen image.
guard CommandLine.arguments.count == 3,
      let input = NSImage(contentsOfFile: CommandLine.arguments[1]),
      let tiff = input.tiffRepresentation,
      let bitmap = NSBitmapImageRep(data: tiff),
      let cg = bitmap.cgImage else { exit(2) }
let detector = CIDetector(ofType: CIDetectorTypeQRCode, context: CIContext(), options: [CIDetectorAccuracy: CIDetectorAccuracyHigh])
let matches = detector?.features(in: CIImage(cgImage: cg)).compactMap { ($0 as? CIQRCodeFeature)?.messageString } ?? []
let pass = matches.contains(CommandLine.arguments[2])
print("QR_MATCH=\(pass ? "true" : "false")")
exit(pass ? 0 : 1)
